head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[secret > P > tooltip]<br/>Secret 컴포넌트 영역으로 마우스가 들어왔을 때 표시할 툴팁을 설정합니다.",
    "validation" : [
        "문자열 값 설정 시, 툴팁에 표시할 텍스트를 설정합니다.",
        "툴팁은 Secret 컴포넌트의 좌상단과 툴팁의 좌하단 위치가 일치하도록 표시되며 해당 위치가 기본 위치가 됩니다.",
        "Secret 컴포넌트가 화면 상단에 위치하여 툴팁이 표시될 공간이 없는 경우 컴포넌트의 좌하단에 표시됩니다.",
        "tooltip 속성을 설정하지 않으면 tooltipLocaleRef 속성은 무시됩니다.",
        "tooltip, tooltipLocaleRef 속성과 config.xml 의 WebSquare/useLocale/@value 를 모두 설정하면 클라이언트 다국어가 적용되고 tooltip 속성값은 무시됩니다.",
        "부모 컴포넌트에 tooltip 속성이 설정되어 있고 Secret 컴포넌트에 tooltip 속성값이 있으면 tooltip 속성과 툴팁 관련 속성이 부모 컴포넌트에 반영(빈값 포함)됩니다.",
        "부모 컴포넌트에 tooltip 속성이 설정되어 있고 Secret 컴포넌트에 tooltip 속성값이 없으면 툴팁 관련 일부 속성만 부모 컴포넌트에 반영(빈값 포함)됩니다.",
        "부모 컴포넌트에 tooltip 속성이 설정되어 있으면 반영된 속성값이 적용된 툴팁이 부모 컴포넌트에 표시됩니다.",
        "스크립트로 disabled 속성을 true 로 변경한 경우에는 툴팁이 표시됩니다.",
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // 정적 select1 은 초기 selectedIndex 가 적용되지 않으므로 기본값을 명시 설정한다.
    //  gdl_boolean 바인딩 항목의 코드값 : 미설정="1" / true="2" / false="3"
    con_tooltip.setValue("secret 툴팁");
    con_tooltipLocaleRef.setValue("");
    con_useLocale.setValue("1");
    con_disabled.setValue("1");
    con_parentTooltip.setValue("");
    con_topPosition.setValue("1");

    // 툴팁은 마우스가 벗어나면 사라지므로, 툴팁이 표시된 상태(마우스 오버 중)의 클릭 시점에 값을 읽는다.
    //  WebSquare 이벤트보다 먼저 동작해야 하므로 capture 단계 native click 리스너를 사용한다.
    document.addEventListener("click", scwin.fn_clickCapture, true);

    // comp 초기 생성
    scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target 있으면 삭제 (자식 Secret 을 먼저 제거한 뒤 부모 group 을 제거한다)
    if (scwin.target1) {
        scwin.target1.remove();
        scwin.target1 = null;
    }

    if (scwin.parent1) {
        scwin.parent1.remove();
        scwin.parent1 = null;
    }

    let cTooltip   = con_tooltip.getValue();
    let cLocaleRef = con_tooltipLocaleRef.getValue();
    let cUseLocale = con_useLocale.getText();
    let cDisabled  = con_disabled.getText();
    let cParentTip = con_parentTooltip.getValue();
    let cTop       = con_topPosition.getText();

    scwin.gVar = {
        "tooltip" : cTooltip,
        "localeRef" : cLocaleRef,
        "useLocale" : cUseLocale,
        "disabled" : cDisabled,
        "parentTip" : cParentTip,
        "top" : cTop,
        "scriptDisabled" : false
    };

    let fnLbl = function (v) { return (v === "") ? "미설정" : v; };

    $c.gcm.createLabel('label="[현재] tooltip = ' + fnLbl(cTooltip) + ' / tooltipLocaleRef = ' + fnLbl(cLocaleRef)
        + ' / useLocale = ' + fnLbl(cUseLocale) + ' / disabled = ' + fnLbl(cDisabled)
        + ' / 부모 group tooltip = ' + fnLbl(cParentTip) + ' / 상단 배치 = ' + fnLbl(cTop)
        + '\n[전제] Secret 은 회색 배경의 부모 group(padding 20px) 안에 생성되므로 부모 group 의 좌상단은 Secret 좌상단보다 20px 바깥입니다'
        + '\n[절차] con 값 변경 -> Target 재생성 -> Secret 위에 마우스를 올려 툴팁이 표시되는 것을 확인한 뒤 Secret 을 클릭'
        + '\n - disabled 케이스 : 비활성 입력창은 클릭이 전달되지 않으므로 툴팁 표시 여부는 화면에서 직접 확인하고, 조건 출력은 회색 부모 영역을 클릭 (마우스가 Secret 을 벗어나면 툴팁이 닫혀 결과창의 display 는 none 으로 출력됩니다)'
        + '\n[확인] 결과창에 조건과 툴팁 텍스트/display, 툴팁·Secret·부모 group 의 위치 수치가 출력됩니다'
        + '\n[참고] 상단 배치 = true 이면 Secret 이 화면 최상단에 고정 배치되어 툴팁이 표시될 상단 공간이 없어집니다"', '', 'label1');

    // 부모 group : 부모 컴포넌트 tooltip 반영 규칙 검증용 (padding 으로 Secret 과 좌상단 위치를 구분한다)
    let pList = $c.gcm.createCList({ tooltip : cParentTip });

    let strParent = '<xf:group ' + $c.gcm.strNameSpace + ' ' + pList
        + ' style="display:inline-block; padding:20px; background-color:var(--ws-gray-200);"></xf:group>';

    scwin.parent1 = await $p.dynamicCreate("parent1", "group", strParent, $c.gcm.getTestGroup(''));

    // 조건 설정
    let properties = {
        tooltip : cTooltip,
        tooltipLocaleRef : cLocaleRef,
        useLocale : cUseLocale,
        disabled : cDisabled,
    };

    let cList = $c.gcm.createCList(properties);

    // 상단 배치 시 화면 최상단에 고정하여 툴팁이 위로 표시될 공간을 없앤다
    let cStyle = (cTop === "true") ? ' style="width:200px; height:40px; position:fixed; top:0px; left:200px; z-index:1000;"'
                                   : ' style="width:200px; height:40px;"';

    // 부모 group 안에 생성해야 하므로 공통 함수($c.gcm.createBasicSecret) 대신 직접 생성한다
    let strTarget = '<xf:secret ' + $c.gcm.strNameSpace + ' ' + cList + cStyle + '></xf:secret>';

    scwin.target1 = await $p.dynamicCreate("target1", "secret", strTarget, scwin.parent1.render);
}



// 부모 group / Secret 영역 클릭 시에만 결과를 출력한다
scwin.fn_clickCapture = function (e) {
    if (!scwin.parent1 || !scwin.parent1.render || !e.target) {
        return;
    }

    if (!scwin.parent1.render.contains(e.target)) {
        return;
    }

    scwin.fn_printTooltip();
};



// validation 항목별 판정 출력
scwin.fn_printTooltip = function () {
    let bottom = wf_body_bottom.getObj("scwin");
    let g = scwin.gVar;

    let fnLbl = function (v) { return (v === "") ? "미설정" : v; };

    // validation 1, 4, 5, 9 판정 조건 (표시 텍스트와 표시 여부는 아래 공통 함수 출력으로 판정)
    bottom.setReturnValue("조건 : tooltip = " + fnLbl(g.tooltip) + " / tooltipLocaleRef = " + fnLbl(g.localeRef)
        + " / useLocale = " + fnLbl(g.useLocale) + " / disabled = " + fnLbl(g.disabled)
        + (g.scriptDisabled === true ? " (스크립트로 setDisabled(true) 적용)" : ""));

    // 표시된 툴팁 텍스트와 display 는 공통 함수로 확인한다
    $c.gcm.getTooltipInfo(wf_body_bottom);

    let tip = document.querySelector(".w2balloonTip");

    if (tip === null || tip.style.display === "none") {
        return;
    }

    let tr = tip.getBoundingClientRect();
    let ir = scwin.target1.render.getBoundingClientRect();
    let pr = scwin.parent1.render.getBoundingClientRect();

    let dx = Math.round(tr.left - ir.left);
    let dUp = Math.round(tr.bottom - ir.top);
    let dDown = Math.round(tr.top - ir.bottom);

    // validation 2, 3 판정 출력 (위치 수치는 공통 함수가 제공하지 않는다)
    let strPos = (dUp === 0) ? "기본 위치 (툴팁 좌하단 = Secret 좌상단, 좌측 차이 " + dx + "px)"
               : (dDown >= 0) ? "Secret 좌하단 아래에 표시 (툴팁 상단 - Secret 하단 = " + dDown + "px, 좌측 차이 " + dx + "px)"
               : "기본 위치/하단 표시 모두 아님";

    bottom.setReturnValue("툴팁 위치 : " + strPos
        + " (툴팁 left/top/bottom = " + Math.round(tr.left) + "/" + Math.round(tr.top) + "/" + Math.round(tr.bottom)
        + ", Secret left/top/bottom = " + Math.round(ir.left) + "/" + Math.round(ir.top) + "/" + Math.round(ir.bottom) + ")");

    // validation 6, 7, 8 판정 출력
    if (g.parentTip !== "") {
        let base = (Math.round(tr.left) === Math.round(pr.left) && Math.round(tr.bottom) === Math.round(pr.top)) ? "부모 group"
                 : (dx === 0 && dUp === 0) ? "Secret"
                 : "판정 불가";

        bottom.setReturnValue("부모 group tooltip = " + g.parentTip + " -> 툴팁 정렬 기준 : " + base
            + " (부모 group left/top = " + Math.round(pr.left) + "/" + Math.round(pr.top) + ")");
    }
};



// 스크립트로 disabled 를 true 로 변경 (속성으로 준 disabled 와 구분하여 확인) - validation 9 전제 설정
scwin.btn_setDisabled_onclick = function (e) {
    scwin.target1.setDisabled(true);
    scwin.gVar.scriptDisabled = true;

    wf_body_bottom.getObj("scwin").setReturnValue("setDisabled(true) 실행 -> getDisabled = " + scwin.target1.getDisabled());
};
